// components/OfflineBanner.js — 오프라인 배너 자리표시자
// 문서 언어: ko-KR / 모듈: frontend_dev_module_2 (scope 문서 §3)
// module_5에서 캐시 기반 폴백 로직을 추가한다. 본 모듈은 status에 따른 hidden 토글만.

/**
 * @param {HTMLElement} el 마운트 지점(slot)
 * @param {import('../state.js').AppStatus} status
 */
export function renderOfflineBanner(el, status) {
  if (!(el instanceof HTMLElement)) return;

  if (status === "offline") {
    el.hidden = false;
    el.setAttribute("role", "status");
    el.setAttribute("aria-live", "polite");
    el.classList.add("offline-banner", "offline-banner--visible");
    el.textContent =
      "오프라인 상태입니다. 마지막으로 저장된 추천을 표시합니다.";
    return;
  }

  el.hidden = true;
  el.classList.remove("offline-banner--visible");
  el.textContent = "";
}

